# Long-case expansion L1 (target ~30 Qs): psoriasis, vesicobullous, vitiligo, SLE, cutaneous TB.
# Own words; viva-length answers. Facts from IADVL 5e, current guidelines.
D = [
dict(case="Psoriasis", qa=[
 ("What are the dermoscopic features of psoriasis?", ["Regularly distributed red dotted (pinpoint) vessels on a light-red background with diffuse white scales", "Scalp: red dots/globules, twisted red loops, white scales; nails: red-dot lunula, oil spots, splinter haemorrhages", "Helps to differentiate from eczema (patchy dotted vessels, yellow crusts) and LP (Wickham's striae)"]),
 ("Describe scalp psoriasis and its treatment.", ["Well-demarcated thick silvery plaques extending beyond the hairline (forehead, ears, nape), itch; non-scarring; pityriasis amiantacea (asbestos-like scales binding hair tufts) is a pattern", "Treatment: keratolytics (salicylic acid 3–6% oil/ointment, coal tar shampoo), steroid lotions/foam/shampoo (clobetasol), calcipotriol–betamethasone gel; systemic/biologics for severe (IL-17 agents work well)"]),
 ("Describe inverse (flexural) and genital psoriasis.", ["Sharply demarcated, glazed red plaques without much scale (moisture) in axillae, groin, inframammary, natal cleft, umbilicus; fissures in folds; genitals — glans/vulva", "Treat with low-potency steroids short-term, calcineurin inhibitors (tacrolimus), calcitriol; rule out candidiasis/ tinea; IL-17 inhibitors effective for genital disease"]),
 ("Describe palmoplantar psoriasis and palmoplantar pustulosis (PPP).", ["Palmoplantar psoriasis: thick hyperkeratotic fissured plaques with sharp borders on palms/soles — disabling", "PPP: crops of sterile yellow pustules evolving to brown macules on thenar/hypothenar eminences and heels; strong link with smoking (stop smoking), thyroid disease, SAPHO syndrome; treat with potent steroids under occlusion, acitretin, PUVA (hand/foot soaks), methotrexate, apremilast, cyclosporine"]),
 ("What is acrodermatitis continua of Hallopeau?", ["Localised pustular psoriasis of fingertips/toes — pustules around and under the nail, nail loss, osteolysis of distal phalanx; very resistant; treat with acitretin, potent topicals, biologics (IL-17/IL-36), cyclosporine"]),
 ("Discuss phototherapy in psoriasis.", ["NB-UVB (311 nm): first-line phototherapy — 3 times/week, start 70% of MED or by skin type, increase 10–20% per session; clearance in ~20–30 sessions; safe in pregnancy and children", "PUVA: oral 8-MOP 0.6 mg/kg (or 5-MOP) 2 h before UVA, twice weekly; more effective for thick plaques/palmoplantar; risks — nausea, phototoxic burns, cataract (eye protection 24 h), photoageing, SCC (dose-dependent >200 sessions), melanoma", "Excimer 308 nm targeted for localised plaques/scalp; combinations — Re-PUVA, NB-UVB + acitretin/ calcipotriol"]),
 ("What is the Goeckerman and Ingram regimen?", ["Goeckerman: crude coal tar applied to plaques followed by UVB exposure daily — classical inpatient regimen", "Ingram: dithranol (anthralin) in Lassar's paste + tar bath + UVB; short-contact dithranol now preferred at home (staining, irritation)"]),
 ("Psoriasis in HIV — what is special?", ["Can be the presenting feature; severe, explosive, erythrodermic, inverse and reactive-arthritis overlap; poor response to usual therapy", "Treat with ART (improves psoriasis), acitretin (not immunosuppressive), phototherapy (with caution); avoid methotrexate/cyclosporine; biologics used cautiously with controlled viral load"]),
 ("What is drug-induced and paradoxical psoriasis?", ["Drug-induced/aggravated: lithium, β-blockers, antimalarials, NSAIDs, interferon, terbinafine, tetracyclines, imiquimod, checkpoint inhibitors (PD-1)", "Paradoxical psoriasis with TNF inhibitors (palmoplantar pustular common) — switch class (IL-12/23, IL-23) if severe"]),
 ]),
dict(case="Vesicobullous diseases (pemphigus / pemphigoid)", qa=[
 ("What are the variants of pemphigus vulgaris?", ["Pemphigus vegetans — Neumann type (erosions heal with vegetations, more severe) and Hallopeau type (pustules evolve to vegetations, milder) in flexures, scalp", "Pemphigus herpetiformis (itchy annular vesicles like DH, anti-Dsg1/3), drug-induced (thiol — penicillamine, captopril; non-thiol — rifampicin, NSAIDs), IgA pemphigus (subcorneal pustular dermatosis type — desmocollin 1; intraepidermal neutrophilic type)"]),
 ("What is the pemphigus disease area index (PDAI)?", ["Validated activity/damage score: skin (12 sites, 0–10 each), scalp (0–10), mucosa (12 sites, 0–10) activity + damage (post-inflammatory hyperpigmentation) — total activity 0–250; mild <15, moderate 15–45, significant >45", "ABSIS (Autoimmune Bullous Skin Disorder Intensity Score) is an alternative"]),
 ("What is the rituximab protocol and monitoring?", ["RA protocol: 1 g IV on day 1 and day 15 (premedicate — paracetamol, antihistamine, methylprednisolone 100 mg); lymphoma protocol 375 mg/m² weekly × 4", "Before: HBsAg/anti-HBc (reactivation), HCV, HIV, TB screen, CBC, immunoglobulins, pregnancy test; avoid live vaccines", "After: CD19/CD20 B-cell counts, anti-Dsg titres; maintenance 500 mg at 6 months (and/or 12, 18) if Dsg ELISA remains high; side effects — infusion reactions, infections, hypogammaglobulinaemia, late neutropenia, PML (rare)"]),
 ("What is mucous membrane pemphigoid (MMP)?", ["Subepidermal autoimmune blistering disease mainly of mucosae (oral — desquamative gingivitis 85%, ocular — conjunctival scarring, symblepharon, blindness; nasal, laryngeal, oesophageal, genital) with scarring", "Antigens: BP180 (C-terminal), laminin 332 (associated with malignancy), α6β4 integrin (ocular)", "Treatment by risk: low-risk (oral/skin only) — topical steroids, dapsone, tetracyclines; high-risk (ocular, laryngeal, oesophageal) — cyclophosphamide/rituximab, IVIG, systemic steroids; ophthalmology follow-up"]),
 ("What is epidermolysis bullosa acquisita (EBA)?", ["Autoantibodies (IgG) against type VII collagen (anchoring fibrils) — mechanobullous type (trauma-induced blisters on extensors healing with scars and milia, nail loss) and inflammatory BP-like type; association with Crohn's disease", "Diagnosis: DIF linear IgG at BMZ with u-serrated pattern, salt-split skin floor binding, ELISA collagen VII", "Treatment difficult: colchicine, dapsone, steroids, rituximab, IVIG"]),
 ("What is linear IgA bullous dermatosis?", ["Linear IgA deposits at BMZ against LAD-1/BP180 (97/120 kDa) — children (chronic bullous disease of childhood: annular 'string of pearls'/'cluster of jewels' blisters around genitals, face) and adults (drug-induced — vancomycin commonest, also captopril, NSAIDs, lithium)", "Treatment: dapsone (rapid), sulfapyridine, steroids; stop drug"]),
 ("What are the salt-split skin findings and their use?", ["Incubating normal skin in 1 M NaCl splits through lamina lucida; IIF with patient serum: roof (epidermal) binding — BP, pemphigoid gestationis, MMP (BP180), LABD; floor (dermal) binding — EBA, anti-laminin 332 MMP, anti-p200 pemphigoid, bullous SLE"]),
 ("Describe the steroid side effects to monitor in pemphigus patients.", ["Metabolic: hyperglycaemia, hypertension, weight gain, dyslipidaemia, hypokalaemia", "Bone: osteoporosis, avascular necrosis of femoral head; eyes: cataract, glaucoma; GI: peptic ulcer; infections: TB, fungal, strongyloides hyperinfection, PCP; skin: striae, acne, atrophy; psychiatric; HPA suppression (taper slowly)", "Prophylaxis: calcium + vitamin D, bisphosphonate, PPI, albendazole/ivermectin, isoniazid prophylaxis if latent TB, regular sugar/BP checks"]),
 ("Why does pemphigus flare in pregnancy and how is it managed?", ["Hormonal/immune changes — flares in first trimester and postpartum; neonatal pemphigus from transplacental IgG (transient blisters, resolve in weeks)", "Treatment: lowest dose prednisolone, topical steroids, IVIG (safe), azathioprine (if needed); avoid mycophenolate, cyclophosphamide, methotrexate; rituximab avoided (B-cell depletion in neonate)"]),
 ("What is the role of anti-desmoglein ELISA?", ["Quantitative anti-Dsg1 and anti-Dsg3 IgG: confirms diagnosis, defines phenotype (mucosal vs mucocutaneous vs foliaceus), monitors activity — Dsg3 index correlates with mucosal, Dsg1 with skin activity; persistently high titres after remission predict relapse; useful to decide rituximab maintenance and stopping therapy"]),
 ("Bullous diseases associated with neurological disorders — explain.", ["Bullous pemphigoid is strongly associated with dementia, Parkinson's disease, stroke, epilepsy, multiple sclerosis — shared BP180/BP230 antigen isoforms expressed in the CNS; neurological disease often precedes BP by years"]),
 ]),
dict(case="Vitiligo", qa=[
 ("What is the Koebner phenomenon in vitiligo and how is it classified?", ["Development of vitiligo at sites of trauma; VIDA/ Koebner classification (Van Geel): type 1 — history of Koebner (1a: aligned on a scar, 1b: induced by repeated friction/pressure); type 2 — clinical observation (2a: lesions at friction sites, 2b: linear/scratch-induced); type 3 — experimentally induced", "Presence suggests active, extending disease and poorer response; avoid friction (tight clothes, rubbing)"]),
 ("What is inflammatory vitiligo and other unusual presentations?", ["Inflammatory: raised erythematous border, itching — active disease", "Trichrome (white, light-brown intermediate zone, normal), quadrichrome (perifollicular repigmentation), pentachrome (blue-grey PIH), confetti (tiny 1–5 mm macules — rapidly progressive), blue vitiligo (PIH in vitiliginous skin), hypochromic/minor vitiligo (dark skin, partial loss), follicular (leucotrichia with little skin involvement)"]),
 ("Explain the oral mini-pulse (OMP).", ["Pasricha regimen: betamethasone or dexamethasone 5 mg (0.1 mg/kg in children) orally on two consecutive days per week (e.g. Saturday–Sunday) for 3–6 months to arrest spread", "Advantages: fewer side effects than daily steroids; side effects — weight gain, insomnia, acne, menstrual irregularity, agitation; not for repigmentation alone — combine with phototherapy/topicals"]),
 ("NB-UVB protocol in vitiligo.", ["Twice or thrice weekly (non-consecutive days); start 200–250 mJ/cm² (or fixed by type) and increase 10–20% per session until faint erythema persisting <24 h; continue at least 6 months and up to 12–24 months if repigmenting; ≥25% repigmentation by 3 months predicts response", "Best response: face, neck, trunk; poor: hands, feet, lips, bony prominences; side effects — erythema, itching, xerosis, tanning of normal skin (contrast); combine with tacrolimus/ calcipotriol"]),
 ("What are JAK inhibitors' role in vitiligo?", ["IFN-γ signals via JAK1/2–STAT1 to induce CXCL9/10, which recruits CD8 T cells; blocking JAK reduces the inflammation", "Topical ruxolitinib 1.5% cream twice daily (≥12 y, NSV, ≤10% BSA) — facial repigmentation F-VASI75 in ~30% at 24 weeks, rising with longer use", "Oral JAK inhibitors (ritlecitinib, upadacitinib, povorcitinib) in trials/off-label (tofacitinib, baricitinib) — work best with light exposure; monitor infections, lipids, thrombosis"]),
 ("What are the patterns of repigmentation?", ["Perifollicular (commonest — from follicular melanocyte reservoir, with phototherapy), marginal (from the edge), diffuse, combined; perifollicular gives best cosmetic result; acral/ glabrous skin lacks follicles hence poor response"]),
 ("What is the minigraft (test graft) test?", ["4–5 punch grafts (1–1.2 mm) placed in the recipient patch; if pigment spreads ≥2–3 mm around grafts within 3 months without Koebner at donor site, disease is stable and suitable for surgery"]),
 ("Describe suction blister epidermal grafting technique.", ["Raise blisters on donor site (thigh) using suction syringes/cups (200–400 mmHg) for 1–3 h; recipient site dermabraded or laser-ablated or frozen to raise blister; donor blister roofs transferred and dressed for 7 days; good colour match, no scarring; post-op NB-UVB/PUVAsol"]),
 ("Discuss chemical leucoderma.", ["Depigmentation from contact with melanocytotoxic chemicals — phenols/catechols: para-tertiary butyl phenol (adhesives, bindi, footwear, rubber), monobenzyl ether of hydroquinone, hair dyes (PPD), detergents, alta, deodorants", "Clues: confetti macules at contact site, history of exposure, may spread beyond (becomes vitiligo in susceptible); stop exposure, treat as vitiligo"]),
 ("What are the side effects of topical steroids and tacrolimus in vitiligo?", ["Steroids: atrophy, telangiectasia, striae, acneiform, hypertrichosis — use intermittent (e.g. 5 days a week or 15 days on/off) and avoid face long-term", "Tacrolimus: burning/stinging initially, folliculitis, alcohol flushing; no atrophy — preferred for face, eyelids, flexures, genitals; continue twice weekly for maintenance (prevents relapse)"]),
 ("Psychosocial aspects and stigma in India.", ["Confusion with leprosy ('safed daag'), marriage difficulties, depression, anxiety, reduced quality of life; use VitiQoL/DLQI; counselling, camouflage, support groups, patient education that it is not contagious"]),
 ("Vitiligo in children — special points.", ["Higher segmental proportion, family history, associated halo naevi, atopy; prefer topical calcineurin inhibitors and mid-potency steroids, NB-UVB from ~6–7 years (cooperative), OMP in active spreading disease; screen thyroid"]),
 ("What is the VASI and how is it calculated?", ["Vitiligo Area Scoring Index = Σ (hand units, 1 HU ≈ 1% BSA) × (residual depigmentation: 100, 90, 75, 50, 25, 10, 0%) over body regions (hands, upper limbs, trunk, lower limbs, feet; face separately — F-VASI); range 0–100; VASI50/75 used in trials"]),
 ("Melanocyte–keratinocyte transplantation (MKTP) — steps.", ["Harvest thin split-thickness skin (1/10 of recipient area) from thigh, trypsinise (0.25% trypsin 37 °C, 50 min) to separate epidermis, prepare cell suspension in medium/patient's serum, apply to dermabraded/laser-ablated recipient area, cover with collagen dressing; repigmentation over 3–6 months; can treat up to 10 times donor area"]),
 ]),
dict(case="Systemic lupus erythematosus", qa=[
 ("Describe acute cutaneous lupus (ACLE) in detail.", ["Localised: malar 'butterfly' rash — symmetrical erythema/oedema across cheeks and nasal bridge, sparing nasolabial folds and eyelids, photosensitive, heals without scarring", "Generalised: photosensitive morbilliform eruption, erythema on dorsa of hands between knuckles (spares joints), periungual erythema", "TEN-like ACLE: widespread epidermal necrosis in active SLE (rare)"]),
 ("What is SCLE and its features?", ["Subacute cutaneous LE: photosensitive non-scarring annular-polycyclic or papulosquamous (psoriasiform) plaques on upper trunk, V of neck, extensor arms (face often spared); ~50% meet SLE criteria (mild, often musculoskeletal); anti-Ro/SSA in 70–90%; HLA-DR3", "Drug-induced SCLE — terbinafine, thiazides, CCBs, PPIs, ACE inhibitors, TNF inhibitors, taxanes, leflunomide, griseofulvin, checkpoint inhibitors"]),
 ("Describe lupus panniculitis and chilblain lupus.", ["Lupus profundus/panniculitis: firm deep nodules on face, upper arms, buttocks, breasts healing with lipoatrophy; lobular lymphocytic panniculitis with hyaline fat necrosis; DLE above in ~1/3; differentiate from subcutaneous panniculitis-like T-cell lymphoma", "Chilblain lupus: tender purple papules/plaques on fingers, toes, nose, ears in cold damp weather; familial form TREX1/SAMHD1 (type I interferonopathy)"]),
 ("What is lupus tumidus?", ["Highly photosensitive, smooth, red, urticarial/ succulent plaques without scale or follicular plugging on face/upper trunk, heal without scarring; dermal mucin and perivascular lymphocytes without interface change; rarely systemic; strong response to antimalarials and sun protection"]),
 ("How is SLE skin involvement scored?", ["CLASI (Cutaneous LE Disease Area and Severity Index): activity (erythema, scale/hypertrophy, mucous membrane lesions, recent hair loss, non-scarring alopecia) and damage (dyspigmentation, scarring/atrophy, scarring alopecia) by anatomical areas"]),
 ("What are the haematological and immunological criteria pitfalls?", ["Lymphopenia/ leucopenia common (not due to drugs), Coombs-positive haemolytic anaemia, ITP (may precede SLE by years — check ANA in young ITP); low C3/C4 with active nephritis; anti-dsDNA rises before flares; high ESR with normal CRP — CRP rise suggests infection or serositis"]),
 ("Discuss neuropsychiatric lupus.", ["19 ACR syndromes: headache, seizures, cognitive dysfunction, mood/anxiety, psychosis, cerebrovascular disease (APS), aseptic meningitis, myelopathy, demyelination, chorea, neuropathies", "Mechanisms: vasculopathy, APS thrombosis, autoantibodies (anti-NMDA, anti-ribosomal P — psychosis), cytokines; MRI, CSF, EEG; treat with steroids + cyclophosphamide/rituximab (inflammatory) or anticoagulation (thrombotic)"]),
 ("How do you manage lupus nephritis briefly?", ["Biopsy-guided: class III/IV ± V — induction with IV methylprednisolone pulses then oral prednisolone + mycophenolate (2–3 g/day) or low-dose IV cyclophosphamide (Euro-Lupus 500 mg every 2 weeks × 6), add belimumab or voclosporin/obinutuzumab; maintenance MMF or azathioprine ≥3–5 years; HCQ, ACE inhibitor/ARB, BP and lipid control; class V — MMF/calcineurin inhibitor + antiproteinuric", "Targets: proteinuria <0.5–0.7 g/day by 12 months"]),
 ("What is the role of hydroxychloroquine — mechanism and dose?", ["Raises lysosomal pH in antigen-presenting cells, inhibits TLR7/9 signalling and type I IFN, reduces antigen presentation; antithrombotic, lipid-lowering, glucose-lowering", "Dose ≤5 mg/kg real body weight/day (usually 200–400 mg); side effects — retinopathy (screen), GI upset, skin pigmentation (blue-grey shins/palate), rash (DRESS rarely), cardiomyopathy and QT prolongation (rare), haemolysis in G6PD (rare), psoriasis flare; safe in pregnancy and breastfeeding"]),
 ("Anifrolumab — what is it?", ["Human monoclonal antibody against type I interferon receptor subunit 1 (IFNAR1); 300 mg IV every 4 weeks for moderate–severe SLE on standard therapy — particularly good for skin (CLASI) and joints; herpes zoster and respiratory infections more frequent"]),
 ("Pregnancy in SLE — counselling points.", ["Plan when disease is quiescent ≥6 months on pregnancy-compatible drugs (HCQ, azathioprine, low-dose prednisolone, tacrolimus); stop MMF, methotrexate, cyclophosphamide ≥3 months earlier", "Risks: flares, pre-eclampsia, fetal loss, preterm birth, neonatal lupus/congenital heart block (anti-Ro — fetal echocardiography weeks 16–26), APS complications; low-dose aspirin from 12 weeks, LMWH if APS"]),
 ("What is the Sjögren's syndrome overlap and its skin features?", ["Secondary Sjögren's in ~15–20% of SLE; sicca (dry eyes/mouth), parotid enlargement, anti-Ro/La; skin — xerosis, annular erythema (Asian), purpura (hypergammaglobulinaemic, cryoglobulinaemic vasculitis), Raynaud's; risk of lymphoma (MALT)"]),
 ("Differentiate the malar rash of SLE from other causes.", ["SLE: spares nasolabial folds, photosensitive, non-scaly, transient with flares", "Rosacea (papules, pustules, flushing, involves nasolabial folds), seborrhoeic dermatitis (greasy scale in nasolabial folds), DM (heliotrope, involves nasolabial folds, violaceous), contact/photo-dermatitis, erysipelas (unilateral, fever), pellagra, tinea faciei, PMLE"]),
 ("What is SLE-associated alopecia?", ["Non-scarring: diffuse telogen effluvium during flares, 'lupus hair' (frontal short broken hairs), alopecia areata-like; scarring alopecia from DLE plaques — permanent; early treatment of scalp DLE prevents scarring"]),
 ("Mention mucosal lesions of lupus.", ["Painless palatal ulcers/erythema (hard palate — a classification criterion), buccal DLE-like white radiating lesions, lip DLE, nasal septal ulceration/perforation, conjunctival lesions"]),
 ("Prognosis and causes of death in SLE.", ["10-year survival >90% now; bimodal mortality — early from active disease (nephritis, CNS) and infections, late from cardiovascular disease (accelerated atherosclerosis) and treatment complications; poor prognosis: nephritis, young male, low socioeconomic status, African/Asian ancestry, APS"]),
 ]),
dict(case="Cutaneous tuberculosis", qa=[
 ("What is the role of IGRA versus Mantoux in skin TB?", ["IGRA (QuantiFERON-TB Gold Plus, T-SPOT.TB) measures IFN-γ release to ESAT-6/CFP-10 — not affected by BCG or most NTM, single visit, but cannot distinguish latent vs active and costly; both support diagnosis in paucibacillary forms and tuberculids when combined with clinical and histological evidence"]),
 ("What are the newer Indian molecular diagnostics?", ["CBNAAT/GeneXpert MTB/RIF and Xpert Ultra, TrueNat MTB/RIF (Indian chip-based, battery-operated) — rapid detection with rifampicin resistance; Line Probe Assay (first- and second-line drugs: INH, FQ, aminoglycosides); MGIT liquid culture for DST — recommended by NTEP for extrapulmonary samples"]),
 ("What is TB-HIV coinfection's effect on skin TB?", ["More multibacillary forms (miliary, gummas, orificial, scrofuloderma), atypical lesions, negative tuberculin, IRIS after ART (paradoxical worsening); give ATT first, start ART within 2–8 weeks depending on CD4; cotrimoxazole prophylaxis"]),
 ]),
]
